// Accept BOTH shapes:
//   GET  /webhook/lead-stage?t=<token>            -- a link clicked by a client
//   POST /webhook/lead-stage {lead_id,facet,to_stage,submittedAt,signature}
// A link click is a GET, so it cannot carry a JSON body or an HMAC header. Tokens
// are single-use and expiring instead -- an HMAC in a URL is replayable forever
// and leaks into browser history and edge logs.
// `token` is also the routing key: Token Path? sends token-bearing requests
// straight to the burn query, and everything else through Fresh & Well-formed?
// -> HMAC Expected -> Signature Valid?, which is all that authenticates a POST.
const raw = $input.first().json;
const q = raw.query ?? {};
const b = (raw.body && typeof raw.body === 'object') ? raw.body : {};
const token = q.t ?? q.token ?? null;
if (token) return [{ json: { token: String(token), lead_id: null, facet: null, to_stage: null } }];
const lead_id = b.lead_id ?? b.leadId ?? null;
const ts = String(b.submittedAt ?? '').trim();
// Freshness, identical to WF-A: Math.abs() so a client clock running ahead of ours
// is caught as well as one running behind, and `!(skew < 300)` rather than
// `skew >= 300` so an unparseable date (Date.parse -> NaN) lands in the reject
// branch instead of sliding through a comparison that is false either way.
const skew = ts ? Math.abs(Date.now() - Date.parse(ts)) / 1000 : Infinity;
// Rejections use WF-C's own idiom -- {ok:false, code, reason} rendered by Respond
// Stage -- and every one of them lands before Resolve Lead / Burn Token. 400 is
// for a malformed request, 401 for one that failed to authenticate.
if (!lead_id || !ts)  return [{ json: { token: null, ok: false, code: 400, reason: 'missing lead_id/timestamp' } }];
if (!(skew < 300))    return [{ json: { token: null, ok: false, code: 401, reason: 'stale or unparseable timestamp' } }];
// The timestamp is INSIDE sigBase, not merely alongside it: signing it is what
// stops a captured signature being replayed once its window has closed.
return [{ json: {
  token: null, ok: true, lead_id: String(lead_id),
  facet: String(b.facet ?? 'commercial'), to_stage: String(b.to_stage ?? ''),
  sigBase: `${lead_id}.${b.facet ?? 'commercial'}.${b.to_stage ?? ''}.${ts}`,
  providedSig: String(b.signature ?? ''),
} }];

// Transition guard. THESE MAPS ARE THE DIAGRAM'S ARROWS.
// Two orthogonal facets: a lead can be payment_pending (commercial) AND
// consult_booked (calendar) at once. One `stage` enum could not hold that, and the
// guard would 4xx a legitimate booking that a poller would never retry.
const COMMERCIAL = {
  lead_in:            ['contacted', 'lost'],
  contacted:          ['proposal_sent', 'lost'],
  proposal_sent:      ['proposal_accepted', 'payment_pending', 'lost'],
  payment_pending:    ['proposal_sent', 'proposal_accepted', 'lost'],  // <- the video's retry loop
  proposal_accepted:  ['client_signed', 'lost'],
  client_signed:      ['engagement_opened'],
  engagement_opened:  [],
  lost:               ['contacted'],
};
const CALENDAR = {
  none:              ['consult_booked'],
  consult_booked:    ['consultation_done', 'none'],   // 'none' = cancelled
  consultation_done: ['consult_booked'],              // follow-up consult
};
const MAPS = { commercial: COMMERCIAL, calendar: CALENDAR };

// Unsubscribing is NOT 'lost'. It is legal from any state, changes no stage column
// (APPLY_SQL only writes a column when facet is commercial|calendar) and only sets
// stopped_at. Marking a signed client 'lost' because they opted out of nurture mail
// would be wrong.
const SYSTEM_STAGES = ['unsubscribed', 'replied', 'bounced'];

const i = $input.first().json;
const row = i.lead_id ? i : null;
if (!row) return [{ json: { ok: false, code: 404, reason: 'lead not found or token invalid/expired/used' } }];

const facet = String(row.facet || '');
const to    = String(row.to_stage || '');
if (facet === 'system') {
  if (!SYSTEM_STAGES.includes(to)) {
    return [{ json: { ok: false, code: 400, reason: `unknown system stage '${to}'` } }];
  }
  return [{ json: { ok: true, noop: false, code: 200, lead_id: row.lead_id, facet,
                    from_stage: row.commercial_stage, to_stage: to, actor: row.actor || 'webhook',
                    name: row.name, email_norm: row.email_norm } }];
}
const map   = MAPS[facet];
if (!map) return [{ json: { ok: false, code: 400, reason: `unknown facet '${facet}'` } }];

const from = facet === 'commercial' ? row.commercial_stage : row.calendar_stage;
if (from === to) {
  // Idempotent replay: already there. Success, but write no duplicate event.
  return [{ json: { ok: true, noop: true, code: 200, lead_id: row.lead_id, facet, from_stage: from, to_stage: to } }];
}
if (!(map[from] || []).includes(to)) {
  return [{ json: { ok: false, code: 409, reason: `illegal transition ${facet}: ${from} -> ${to}`,
                    lead_id: row.lead_id, allowed: map[from] || [] } }];
}
return [{ json: { ok: true, noop: false, code: 200, lead_id: row.lead_id, facet,
                  from_stage: from, to_stage: to, actor: row.actor || 'webhook',
                  name: row.name, email_norm: row.email_norm } }];
